int find_nearest_index(const float *arr, size_t n, float value)
{
    size_t idx_min = 0;
    float min_dist = fabsf(arr[0] - value);

    for (size_t i = 1; i < n; i++)
    {
        float dist = fabsf(arr[i] - value);

        if (dist < min_dist)
        {
            min_dist = dist;
            idx_min = i;
        }
    }
    return (int)idx_min;
}




